PACKAGES = ['linkwatch']
ENTRY_POINTS = {'linkwatch': 'linkwatch.cli:cli'}

import contextlib, importlib, io, json, pkgutil, sys
results = {}
for pkg in PACKAGES:
    try:
        mod = importlib.import_module(pkg)
    except Exception as e:
        results["import " + pkg] = {"error": type(e).__name__ + ": " + str(e)[:200]}
        continue
    results["import " + pkg] = "ok"
    for info in pkgutil.walk_packages(getattr(mod, "__path__", []), pkg + "."):
        try:
            importlib.import_module(info.name)
            results["import " + info.name] = "ok"
        except Exception as e:
            results["import " + info.name] = {"error": type(e).__name__ + ": " + str(e)[:200]}
for name, target in ENTRY_POINTS.items():
    mod_name, _, attr = target.partition(":")
    out = io.StringIO()
    code = None
    try:
        func = importlib.import_module(mod_name)
        for part in attr.split("."):
            func = getattr(func, part)
        sys.argv = [name, "--help"]
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(out):
            try:
                func()
            except SystemExit as e:
                code = e.code
        results["cli " + name + " --help"] = {"exit": code, "output": out.getvalue()}
    except Exception as e:
        results["cli " + name + " --help"] = {"error": type(e).__name__ + ": " + str(e)[:200]}
print(json.dumps(results, sort_keys=True, default=repr))

import os
import json
import tempfile
from linkwatch.cache import cache_dir, cache_file, save_results, load_results

results = {}

def run_case(name, action):
    try:
        res = action()
        results[name] = res
    except Exception as e:
        results[name] = {"error": f"{type(e).__name__}: {str(e)}"}

# 1. Default behavior (tests appdirs.user_cache_dir fallback)
def case_default():
    if "LINKWATCH_CACHE_DIR" in os.environ:
        del os.environ["LINKWATCH_CACHE_DIR"]
    return str(cache_dir())
run_case("default_dir", case_default)

# 2. Custom path via environment variable
def case_env():
    tmp = tempfile.mkdtemp()
    os.environ["LINKWATCH_CACHE_DIR"] = tmp
    return str(cache_dir())
run_case("env_dir", case_env)

# 3. Path with spaces to check path handling
def case_spaces():
    tmp = os.path.join(tempfile.mkdtemp(), "space test")
    os.environ["LINKWATCH_CACHE_DIR"] = tmp
    return str(cache_dir())
run_case("space_dir", case_spaces)

# 4. Empty string environment variable (should trigger fallback to appdirs)
def case_empty():
    os.environ["LINKWATCH_CACHE_DIR"] = ""
    return str(cache_dir())
run_case("empty_env_dir", case_empty)

# 5. Roundtrip save and load with unicode data
def case_roundtrip():
    tmp = tempfile.mkdtemp()
    os.environ["LINKWATCH_CACHE_DIR"] = tmp
    test_data = [{"key": "val", "unicode": "🚀"}, {"list": [1, 2, 3]}]
    save_results(test_data)
    return load_results()
run_case("roundtrip", case_roundtrip)

# 6. Load results when the file does not exist
def case_missing():
    tmp = tempfile.mkdtemp()
    os.environ["LINKWATCH_CACHE_DIR"] = tmp
    return load_results()
run_case("load_missing", case_missing)

