import json
import os
import tempfile
from typing import List, Dict, Any

from linkwatch.config import load_settings, Settings, Site

def run_probe() -> Dict[str, Any]:
    results = {}

    def create_toml_file(content: str) -> str:
        fd, path = tempfile.mkstemp(suffix=".toml")
        with os.fdopen(fd, 'w') as f:
            f.write(content)
        return str(path)

    # Test cases for toml.load and Settings validation
    # Format: (case_name, toml_content, expected_error_hint)
    test_inputs = [
        ("valid_basic", 'title = "Test"\noutput = "out.html"\n[[sites]]\nname = "S1"\nurl = "http://s1.com"', None),
        ("valid_whitespace_strip", 'title = "  Space  "\n[[sites]]\nname = "  S2  "\nurl = "  http://s2.com  "', None),
        ("empty_sites", 'title = "No Sites"', None),
        ("missing_title", 'output = "out.html"', "title"),
        ("extra_fields", 'title = "Extra"\nunknown_key = 123', "extra"),
        ("empty_name", 'title = "X"\n[[sites]]\nname = ""\nurl = "http://s.com"', "name"),
        ("no_scheme", 'title = "X"\n[[sites]]\nname = "S1"\nurl = "s1.com"', "url"),
        ("malformed_toml", 'title = "Unclosed quote', "toml"),
        ("numeric_title", 'title = 123\noutput = "out.html"', "title"),
        ("nested_table_ignored", 'title = "X"\n[ignored]\nkey = 1', None),
    ]

    for name, content, _ in test_inputs:
        try:
            path = create_toml_file(content)
            try:
                data = load_settings(path)
                results[name] = {"status": "success", "data": data.dict()}
            except Exception as e:
                results[name] = {"status": "error", "error": type(e).__name__ + ": " + str(e)}
            finally:
                if os.path.exists(path):
                    os.remove(path)
        except Exception as e:
            results[name] = {"status": "error", "error": type(e).__name__ + ": " + str(e)}

    print(json.dumps(results, sort_keys=True, default=repr))

if __name__ == "__main__":
    run_probe()
